import { Navbar as BSNavbar, Nav, Button } from 'react-bootstrap';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { logout } from '../store';
import axios from 'axios';

const Navbar = () => {
  const user = useSelector((state: any) => state.auth.user);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleLogout = () => {
    axios
      .post('/api/players/logout', {}, { withCredentials: true })
      .then(() => {
        dispatch(logout());
        navigate('/');
      })
      .catch(err => console.error('Logout failed:', err.response?.data || err.message));
  };

  return (
    <BSNavbar bg="light" expand="lg">
      <BSNavbar.Brand href="/">Game Matchmaking</BSNavbar.Brand>
      <BSNavbar.Toggle />
      <BSNavbar.Collapse>
        <Nav className="me-auto">
          <Nav.Link href="/">Maps</Nav.Link>
          {user && <Nav.Link href="/games">My Games</Nav.Link>}
          {user && <Nav.Link href="/game-constructor">Constructor</Nav.Link>}
        </Nav>
        <Nav>
          {user ? (
            <>
              <Nav.Link disabled>{user.username}</Nav.Link>
              <Button onClick={handleLogout}>Logout</Button>
            </>
          ) : (
            <>
              <Nav.Link href="/login">Login</Nav.Link>
              <Nav.Link href="/register">Register</Nav.Link>
            </>
          )}
        </Nav>
      </BSNavbar.Collapse>
    </BSNavbar>
  );
};

export default Navbar;
